const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Helpers
  const getInfoAsync = (obj) =>
    new Promise((resolve, reject) => obj.getInfo(resolve, reject));

  // 1. Geometry & Time Definitions
  const center = ee.Geometry.Point([-73.845369, -9.799994]);
  const region = center.buffer(5000); // 5 km radius
  const dateA = '2017-08-23';
  const dateB = '2022-08-21';
  const forestNdviThresh = 0.7;

  // 2. Masking and dataset helpers
  function maskS2SR(img) {
    const scl = img.select('SCL');
    const mask = scl.neq(0).and(scl.neq(1)).and(scl.neq(3))
      .and(scl.neq(7)).and(scl.neq(8)).and(scl.neq(9)).and(scl.neq(10));
    return img.updateMask(mask);
  }
  function maskS2L1C(img) {
    const qa = img.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0).and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return img.updateMask(mask);
  }
  function scaleMaskLandsatL2(img) {
    const qa = img.select('QA_PIXEL');
    const mask = qa.bitwiseAnd(1 << 1).eq(0) // Dilated cloud
      .and(qa.bitwiseAnd(1 << 2).eq(0))      // Cirrus
      .and(qa.bitwiseAnd(1 << 3).eq(0))      // Cloud
      .and(qa.bitwiseAnd(1 << 4).eq(0))      // Cloud shadow
      .and(qa.bitwiseAnd(1 << 5).eq(0));     // Snow
    const optical = img.select(['SR_B2','SR_B3','SR_B4','SR_B5','SR_B6','SR_B7'])
      .multiply(0.0000275).add(-0.2);
    return img.addBands(optical, null, true).updateMask(mask);
  }

  function getCollectionAttempt(dateStr, days, type) {
    const start = ee.Date(dateStr).advance(-days, 'day');
    const end = ee.Date(dateStr).advance(days + 1, 'day');
    if (type === 'S2_SR') {
      return ee.ImageCollection('COPERNICUS/S2_SR')
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
    } else if (type === 'S2_L1C') {
      return ee.ImageCollection('COPERNICUS/S2')
        .filterBounds(region)
        .filterDate(start, end)
        .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
    } else { // LANDSAT_L2
      const lc8 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').filterBounds(region).filterDate(start, end);
      const lc9 = ee.ImageCollection('LANDSAT/LC09/C02/T1_L2').filterBounds(region).filterDate(start, end);
      return lc8.merge(lc9);
    }
  }

  async function pickBestCollection(dateStr) {
    const attempts = [
      {type: 'S2_SR', days: 15},
      {type: 'S2_SR', days: 45},
      {type: 'S2_L1C', days: 15},
      {type: 'S2_L1C', days: 45},
      {type: 'LANDSAT_L2', days: 30},
      {type: 'LANDSAT_L2', days: 60},
    ];
    for (let att of attempts) {
      const col = getCollectionAttempt(dateStr, att.days, att.type);
      const size = await getInfoAsync(col.size());
      if (size > 0) return {col, used: att.type, days: att.days, size};
    }
    return {col: null, used: null, days: null, size: 0};
  }

  function ndviComposite(col, used) {
    let ndviCol;
    if (used === 'S2_SR') {
      ndviCol = col.map(maskS2SR).map(function(img) {
        const ndvi = img.normalizedDifference(['B8','B4']).rename('ndvi');
        return ndvi.copyProperties(img, img.propertyNames());
      });
    } else if (used === 'S2_L1C') {
      ndviCol = col.map(maskS2L1C).map(function(img) {
        const ndvi = img.normalizedDifference(['B8','B4']).rename('ndvi');
        return ndvi.copyProperties(img, img.propertyNames());
      });
    } else { // LANDSAT_L2
      ndviCol = col.map(scaleMaskLandsatL2).map(function(img) {
        const ndvi = img.normalizedDifference(['SR_B5','SR_B4']).rename('ndvi');
        return ndvi.copyProperties(img, img.propertyNames());
      });
    }
    return ndviCol.median().rename('ndvi');
  }

  async function computeStatsForDate(dateStr) {
    const pick = await pickBestCollection(dateStr);
    if (!pick.col) return {status: 'C1'};
    const ndviImg = ndviComposite(pick.col, pick.used);

    const ones = ee.Image.constant(1).rename('ones');
    const pixelArea = ee.Image.pixelArea();
    const validArea = ones.updateMask(ndviImg.mask()).multiply(pixelArea)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      }).get('ones');
    const forestArea = ones.updateMask(ndviImg.gt(forestNdviThresh)).multiply(pixelArea)
      .reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: region,
        scale: 1000,
        maxPixels: 1e9
      }).get('ones');

    const validAreaM2 = await getInfoAsync(ee.Number(validArea));
    const forestAreaM2 = await getInfoAsync(ee.Number(forestArea));
    const regAreaM2 = await getInfoAsync(region.area(1));

    if (validAreaM2 === null || forestAreaM2 === null || regAreaM2 === null) return {status: 'C3'};

    const valid0 = (validAreaM2 <= 0);
    if (valid0) return {
      status: 'C2',
      used: pick.used,
      days: pick.days,
      size: pick.size,
      validAreaM2: 0,
      forestAreaM2: 0,
      regAreaM2
    };

    // Basic sanity: forest cannot exceed valid area by large margin; clamp for safety
    const forestClamped = Math.max(0, Math.min(forestAreaM2, regAreaM2));

    const cloudPct = Math.max(0, Math.min(100, 100 * (1 - validAreaM2 / regAreaM2)));

    return {
      status: 'OK',
      used: pick.used,
      days: pick.days,
      size: pick.size,
      validAreaM2,
      forestAreaM2: forestClamped,
      regAreaM2,
      cloudPct
    };
  }

  try {
    const regionAreaM2 = await getInfoAsync(region.area(1));
    console.log(`Region_km2: ${(regionAreaM2 / 1e6).toFixed(2)}`);

    const statsA = await computeStatsForDate(dateA);
    if (statsA.status === 'C1') { console.log(`2017-08-23: No images found (after fallbacks).`); console.log('C1'); return; }
    if (statsA.status === 'C2') {
      const cp = 100 * (1 - (statsA.validAreaM2 / statsA.regAreaM2));
      console.log(`2017-08-23 -> Used:${statsA.used} win:${statsA.days}d imgs:${statsA.size} valid_km2:0.00 cloud%:${Math.max(0, Math.min(100, cp)).toFixed(1)} forest_km2:0.00`);
      console.log('C2'); return;
    }
    if (statsA.status === 'C3') { console.log(`2017-08-23: Calculation failure.`); console.log('C3'); return; }

    const statsB = await computeStatsForDate(dateB);
    if (statsB.status === 'C1') { console.log(`2022-08-21: No images found (after fallbacks).`); console.log('C1'); return; }
    if (statsB.status === 'C2') {
      const cp = 100 * (1 - (statsB.validAreaM2 / statsB.regAreaM2));
      console.log(`2022-08-21 -> Used:${statsB.used} win:${statsB.days}d imgs:${statsB.size} valid_km2:0.00 cloud%:${Math.max(0, Math.min(100, cp)).toFixed(1)} forest_km2:0.00`);
      console.log('C2'); return;
    }
    if (statsB.status === 'C3') { console.log(`2022-08-21: Calculation failure.`); console.log('C3'); return; }

    // Print concise stats
    console.log(`${dateA} -> Used:${statsA.used} win:${statsA.days}d imgs:${statsA.size} valid_km2:${(statsA.validAreaM2/1e6).toFixed(2)} cloud%:${statsA.cloudPct.toFixed(1)} forest_km2:${(statsA.forestAreaM2/1e6).toFixed(2)}`);
    console.log(`${dateB} -> Used:${statsB.used} win:${statsB.days}d imgs:${statsB.size} valid_km2:${(statsB.validAreaM2/1e6).toFixed(2)} cloud%:${statsB.cloudPct.toFixed(1)} forest_km2:${(statsB.forestAreaM2/1e6).toFixed(2)}`);

    // Validate numbers are finite
    const fA = statsA.forestAreaM2, fB = statsB.forestAreaM2;
    if (!isFinite(fA) || !isFinite(fB)) { console.log('C3'); return; }

    const deltaKm2 = (fB - fA) / 1e6;
    console.log(`Delta_forest_km2: ${deltaKm2.toFixed(2)}`);

    if (fB > fA) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (e) {
    console.log(`Error: ${e}`);
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
